<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$key=trim((string)$_POST['key']);$value=(string)$_POST['value'];if($key!==''){$pdo->prepare('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)')->execute([$key,$value]);flash('Paramètre enregistré');}redirect_self();}
$rows=[];try{$rows=$pdo->query('SELECT `key`,`value`,updated_at FROM settings ORDER BY `key`')->fetchAll();}catch(Throwable $e){}admin_layout_start('Réglages');echo '<div class="panel"><p>Les clés API et mots de passe restent dans <code>config/config.local.php</code>. Cette section sert aux paramètres non secrets de la boutique.</p></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input name="key" placeholder="Clé" required><input name="value" placeholder="Valeur"><button>Enregistrer</button></form><table><tr><th>Clé</th><th>Valeur</th><th>Mis à jour</th></tr>';foreach($rows as $r)echo '<tr><td>'.h($r['key']).'</td><td>'.h($r['value']).'</td><td>'.h($r['updated_at']).'</td></tr>';echo '</table>';admin_layout_end();